import React, { useState, useEffect } from "react";

const SpeechRecognition =
  window.SpeechRecognition || window.webkitSpeechRecognition;

const recognition = SpeechRecognition ? new SpeechRecognition() : null;

function Interview() {
  const questions = [
    "Tell me about yourself",
    "What is React?",
    "What are your strengths?",
    "Why should we hire you?"
  ];

  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [listening, setListening] = useState(false);
  const [transcript, setTranscript] = useState("");
  const [score, setScore] = useState(null);

  // ---------------- SPEECH SETUP ----------------
  useEffect(() => {
    if (!recognition) {
      console.log("Speech Recognition not supported");
      return;
    }

    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = "en-US";

    recognition.onresult = (event) => {
      let finalText = "";

      for (let i = event.resultIndex; i < event.results.length; i++) {
        const text = event.results[i][0].transcript;

        if (event.results[i].isFinal) {
          finalText += text;
        }
      }

      setTranscript((prev) => prev + " " + finalText);
    };

    recognition.onerror = (err) => {
      console.log("Speech Error:", err);
    };
  }, []);

  // ---------------- START ----------------
  const startListening = () => {
    if (!recognition) return;

    setTranscript("");
    setScore(null);

    if (!listening) {
      recognition.start();
      setListening(true);
    }
  };

  // ---------------- STOP + SCORE ----------------
  const stopListening = () => {
    if (!recognition) return;

    recognition.stop();
    setListening(false);

    const finalScore = evaluateAnswer(
      transcript,
      questions[currentQuestion]
    );

    setScore(finalScore);
  };

  // ---------------- NEXT QUESTION ----------------
  const nextQuestion = () => {
    if (currentQuestion < questions.length - 1) {
      setCurrentQuestion(currentQuestion + 1);
      setTranscript("");
      setScore(null);
    }
  };

  // ---------------- SIMPLE AI SCORING ----------------
  const evaluateAnswer = (answer, question) => {
    let score = 0;
    const text = answer.toLowerCase();

    const keywords = {
      "Tell me about yourself": ["name", "study", "student", "developer", "experience"],
      "What is React?": ["component", "state", "props", "library", "frontend"],
      "What are your strengths?": ["hardworking", "learning", "team", "confident"],
      "Why should we hire you?": ["skills", "value", "growth", "company", "contribute"]
    };

    const list = keywords[question] || [];

    list.forEach((key) => {
      if (text.includes(key)) {
        score += 20;
      }
    });

    // minimum / maximum control
    if (score === 0 && text.length > 20) {
      score = 40; // basic answer bonus
    }

    return Math.min(score, 100);
  };

  // ---------------- UI ----------------
  return (
    <div style={{ padding: "20px", fontFamily: "Arial" }}>
      <h2>🤖 AI Mock Interview</h2>

      <h3>Question:</h3>
      <p>{questions[currentQuestion]}</p>

      {/* Buttons */}
      <button onClick={startListening} disabled={listening}>
        🎤 Start Speaking
      </button>

      <button onClick={stopListening} disabled={!listening}>
        ⛔ Stop
      </button>

      <button onClick={nextQuestion}>
        ➡ Next Question
      </button>

      {/* Answer Box */}
      <div
        style={{
          marginTop: "20px",
          padding: "10px",
          border: "1px solid gray",
          minHeight: "80px"
        }}
      >
        <h4>Your Answer:</h4>
        <p>{transcript}</p>
      </div>

      {/* SCORE */}
      {score !== null && (
        <h3 style={{ marginTop: "15px" }}>
          🎯 Score: {score}/100
        </h3>
      )}
    </div>
  );
}

export default Interview;
